            "target": "base/fields/date-picker/index.tsx",
            "content": "'use client'\n\nimport { format } from 'date-fns'\nimport { CalendarIcon } from 'lucide-react'\nimport { Popover as PopoverPrimitive } from 'radix-ui'\nimport { cn } from '@/lib/utils'\nimport { FieldCalendar } from '../shared/calendar'\nimport { FieldClearButton, FieldPopoverContent, fieldTriggerClassName } from '../shared/field'\n\nexport function DatePicker({\n  value,\n  onChange,\n  disabled,\n  placeholder = 'Pick a date',\n  className,\n}: {\n  value?: Date\n  onChange?: (date: Date | undefined) => void\n  disabled?: boolean\n  placeholder?: string\n  className?: string\n}) {\n  return (\n    <PopoverPrimitive.Root data-slot=\"field-popover\">\n      <div className={cn('relative w-full', className)}>\n        <PopoverPrimitive.Trigger data-slot=\"field-popover-trigger\" asChild>\n          <button\n            type=\"button\"\n            disabled={disabled}\n            className={cn(\n              fieldTriggerClassName,\n              !value && 'text-muted-foreground',\n              value && !disabled && 'pr-8',\n            )}\n          >\n            <CalendarIcon className=\"mr-2 size-4\" />\n            <span className=\"min-w-0 flex-1 truncate text-left\">\n              {value ? format(value, 'PPP') : placeholder}\n            </span>\n          </button>\n        </PopoverPrimitive.Trigger>\n        {value && !disabled && (\n          <FieldClearButton\n            label=\"Clear date\"\n            onClear={() => onChange?.(undefined)}\n            className=\"absolute top-1/2 right-2 z-10 ml-0 -translate-y-1/2\"\n          />\n        )}\n      </div>\n      <FieldPopoverContent className=\"w-auto p-0\" align=\"start\">\n        <FieldCalendar mode=\"single\" selected={value} onSelect={onChange} />\n      </FieldPopoverContent>\n    </PopoverPrimitive.Root>\n  )\n}\n\nexport function DateRangePicker({\n  value,\n  onChange,\n  disabled,\n  placeholder = 'Pick date range',\n  className,\n}: {\n  value?: { from?: Date; to?: Date }\n  onChange?: (value: { from?: Date; to?: Date } | undefined) => void\n  disabled?: boolean\n  placeholder?: string\n  className?: string\n}) {\n  const from = value?.from\n  const to = value?.to\n\n  return (\n    <PopoverPrimitive.Root data-slot=\"field-popover\">\n      <div className={cn('relative w-full', className)}>\n        <PopoverPrimitive.Trigger data-slot=\"field-popover-trigger\" asChild>\n          <button\n            type=\"button\"\n            disabled={disabled}\n            className={cn(\n              fieldTriggerClassName,\n              !from && 'text-muted-foreground',\n              from && !disabled && 'pr-8',\n            )}\n          >\n            <CalendarIcon className=\"mr-2 size-4\" />\n            <span className=\"min-w-0 flex-1 truncate text-left\">\n              {from && to\n                ? `${format(from, 'LLL dd, y')} - ${format(to, 'LLL dd, y')}`\n                : from\n                  ? format(from, 'LLL dd, y')\n                  : placeholder}\n            </span>\n          </button>\n        </PopoverPrimitive.Trigger>\n        {from && !disabled && (\n          <FieldClearButton\n            label=\"Clear date range\"\n            onClear={() => onChange?.(undefined)}\n            className=\"absolute top-1/2 right-2 z-10 ml-0 -translate-y-1/2\"\n          />\n        )}\n      </div>\n      <FieldPopoverContent className=\"w-auto p-0\" align=\"start\">\n        <FieldCalendar\n          mode=\"range\"\n          selected={{ from, to }}\n          onSelect={(range) => {\n            if (!range) {\n              onChange?.(undefined)\n              return\n            }\n            onChange?.({ from: range.from, to: range.to })\n          }}\n          numberOfMonths={2}\n        />\n      </FieldPopoverContent>\n    </PopoverPrimitive.Root>\n  )\n}\n",
